CREATE DATABASE IF NOT EXISTS csa09_assignment5;
USE csa09_assignment5;
CREATE TABLE IF NOT EXISTS bus_pass(pass_id VARCHAR(32) PRIMARY KEY,reg_no VARCHAR(32) NOT NULL,name VARCHAR(200) NOT NULL,route_no INT NOT NULL,amount DECIMAL(10,2) NOT NULL CHECK(amount>=0),INDEX idx_route(route_no)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bus_pass_benchmark(pass_id VARCHAR(32) PRIMARY KEY,reg_no VARCHAR(32) NOT NULL,name VARCHAR(200) NOT NULL,route_no INT NOT NULL,amount DECIMAL(10,2) NOT NULL CHECK(amount>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student(reg_no VARCHAR(32) PRIMARY KEY,name VARCHAR(200) NOT NULL,course_code VARCHAR(32) NOT NULL,year INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS wallet(wallet_id VARCHAR(32) PRIMARY KEY,balance DECIMAL(12,2) NOT NULL CHECK(balance>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS login_test(user_id VARCHAR(64) PRIMARY KEY,password_value VARCHAR(200) NOT NULL) ENGINE=InnoDB;
INSERT INTO login_test VALUES('demo','correct-only-for-local-test') ON DUPLICATE KEY UPDATE password_value=VALUES(password_value);
